struct AppState {
    mcp: crate::mcp::Bridge,
    jobs: Arc<RwLock<HashMap<Uuid, Arc<RwLock<Job>>>>>,
    data_dir: Arc<PathBuf>,
    exports: sitemap_csv_stream::ExportRegistry,
    finding_reads: sitemap_findings_reads::ReadRegistry,
    lifecycle: lifecycle::Lifecycle,
}
struct Job {
    id: Uuid,
    config: CrawlConfig,
    status: String,
    started_at: String,
    finished_at: Option<String>,
    pages: Vec<PageRecord>,
    issues: Vec<AuditIssue>,
    queued: usize,
    discovery_pending: usize,
    in_flight: usize,
    warnings: Vec<String>,
    error: Option<String>,
    report: Option<CrawlReport>,
    control: CrawlControl,
    generation: u64,
    checkpoint: Option<CrawlCheckpoint>,
    frontier_available: bool,
    operation: Option<SelectedRecrawlOperation>,
    recrawl_override: RecrawlResumeOverride,
    quota_increases: Option<open_seo_spider_core::CrawlQuotaIncreases>,
    policy_ledger: Option<open_seo_spider_core::PolicyLedgerSummary>,
    resource_ledger: Option<open_seo_spider_core::ResourceLedgerSummary>,
}
#[derive(Serialize, Deserialize)]
struct JobManifest {
    id: Uuid,
    config: CrawlConfig,
    status: String,
    started_at: String,
    finished_at: Option<String>,
    #[serde(default)]
    generation: u64,
    #[serde(default)]
    checkpoint: Option<CrawlCheckpoint>,
}
impl Job {
    fn manifest(&self) -> JobManifest {
        JobManifest {
            id: self.id,
            config: self.config.clone(),
            status: self.status.clone(),
            started_at: self.started_at.clone(),
            finished_at: self.finished_at.clone(),
            generation: self.generation,
            checkpoint: self.checkpoint.clone(),
        }
    }
    fn status(&self) -> Value {
        let failed = self
            .pages
            .iter()
            .filter(|page| {
                page.error.is_some() || page.final_status.is_some_and(|status| status >= 400)
            })
            .count();
        let active = matches!(self.status.as_str(), "running" | "pausing" | "cancelling");
        let mut value = json!({"id":self.id,"status":self.status,"seed_url":self.config.seed_urls.first(),"config":self.config,"started_at":self.started_at,"finished_at":self.finished_at,"generation":self.generation,"checkpoint":self.checkpoint,"operation":self.operation,"policy_ledger":self.policy_ledger,"resource_ledger":self.resource_ledger,"resume_available":self.frontier_available && !active,"recrawl_available":self.report.is_some() && !active && self.config.crawl_quotas.is_none(),"parent_snapshot_available":self.operation.is_some() && self.frontier_available,"stats":{"discovered":self.pages.len()+self.queued+self.in_flight,"queued":self.queued,"discovery_pending":self.discovery_pending,"fetched":self.pages.len(),"failed":failed,"issues":self.issues.len(),"in_flight":self.in_flight},"warnings":self.warnings,"error":self.error,"summary":self.report.as_ref().map(|report| &report.summary)});
        if let Some(counts) =
            open_seo_spider_core::reporting_visibility(&self.config, &self.pages, &self.issues)
        {
            value["reporting_visibility"] = json!(counts);
        }
        value
    }
}
#[derive(Serialize)]
struct ApiError {
    error: String,
}
type ApiResult<T> = Result<T, (StatusCode, Json<ApiError>)>;
fn api_error(code: StatusCode, message: impl ToString) -> (StatusCode, Json<ApiError>) {
    (
        code,
        Json(ApiError {
            error: message.to_string(),
        }),
    )
}

pub async fn serve(listen: &str, data_dir: PathBuf) -> anyhow::Result<()> {
    serve_with_mcp_files(listen, data_dir, None).await
}

pub async fn serve_with_mcp_files(
    listen: &str,
    data_dir: PathBuf,
    mcp_files_dir: Option<PathBuf>,
) -> anyhow::Result<()> {
    serve_with_mcp_files_ready(listen, data_dir, mcp_files_dir, None).await
}

pub(crate) async fn serve_with_mcp_files_ready(
    listen: &str,
    data_dir: PathBuf,
    mcp_files_dir: Option<PathBuf>,
    ready: Option<tokio::sync::oneshot::Sender<std::net::SocketAddr>>,
) -> anyhow::Result<()> {
    serve_with_mcp_files_ready_source(
        listen,
        data_dir,
        mcp_files_dir,
        ready,
        lifecycle::ShutdownSource::CtrlC,
    )
    .await
}

pub async fn serve_with_owned_stdin(
    listen: &str,
    data_dir: PathBuf,
    mcp_files_dir: Option<PathBuf>,
) -> anyhow::Result<()> {
    serve_with_mcp_files_ready_source(
        listen,
        data_dir,
        mcp_files_dir,
        None,
        lifecycle::ShutdownSource::OwnedStdin,
    )
    .await
}

async fn serve_with_mcp_files_ready_source(
    listen: &str,
    data_dir: PathBuf,
    mcp_files_dir: Option<PathBuf>,
    ready: Option<tokio::sync::oneshot::Sender<std::net::SocketAddr>>,
    source: lifecycle::ShutdownSource,
