    anyhow::ensure!(
        encoded.len() <= limits.max_input_bytes.div_ceil(3) * 4,
        "Encoded input exceeds max_input_bytes"
    );
    let bytes = STANDARD.decode(encoded)?;
    anyhow::ensure!(
        bytes.len() <= limits.max_input_bytes,
        "Input exceeds max_input_bytes"
    );
    Ok(bytes)
}
