    for index in [0, 2] { r.pages[index].meta_robots = vec!["noindex".into()]; }
    r.config.directive_reporting = Some(profile(1));
    for url in ["https://x/mixed", "https://x/only-hidden", "https://x/visible", "https://x/orphan"] { r.issues.push(AuditIssue { code: "x".into(), severity: Severity::Warning, url: url.into(), message: "original".into(), related_urls: vec!["https://x/only-hidden".into()] }); }
    let before = serde_json::to_vec(&r).unwrap();
    let all = project_with_reporting(&r, &Rules::default(), &Selection::All, None).unwrap();
    assert_eq!(all.pages.iter().map(|p| p.page_ordinal).collect::<Vec<_>>(), vec![1, 3]);
