    assert_eq!(all.orphan_issues, 1, "A known hidden URL never becomes an orphan");
    let meta = all.reporting.unwrap();
    assert_eq!((meta.captured_issues, meta.profile_visible_issues, meta.profile_excluded_issues, meta.selected_issues, meta.captured_orphan_issues), (4, 3, 1, 2, 1));
    let selected = project_with_reporting(&r, &rules(vec![d("hidden", Field::StoredTitle, Operator::Equals, "hidden")]), &Selection::Segment { id: "hidden".into() }, None).unwrap();
    assert!(selected.pages.is_empty() && selected.issues.is_empty(), "Hidden matching duplicate cannot select the visible duplicate's issue");
