fn segments_export_byte_boundary_and_utf8_rule_ceiling_are_exact() {
    let exact = "x".repeat(OUTPUT_BYTES - 2); // JSON quote pair occupies the remaining two bytes.
    assert_eq!(json_bytes(&exact).unwrap().len(), OUTPUT_BYTES);
