}
fn reporting_report() -> CrawlReport {
    let mut r = report(vec![p("https://x/plain", Some("yes"), Some(200)), p("https://x/noindex", Some("yes"), Some(404)), p("https://x/canonical", Some("yes"), Some(200)), p("https://x/prev", Some("yes"), Some(200)), p("https://x/next", Some("yes"), Some(200))]);
    r.pages[1].meta_robots = vec!["noindex".into()];
    r.pages[2].canonical = vec!["https://x/target-only".into()];
    r.pages[3].pagination_prev = vec!["https://x/target-only".into()];
    r.pages[4].pagination_next = vec!["https://x/target-only".into()];
    r.pages[4].canonical = vec![r.pages[4].url.clone()];
    r.pages[4].links.push(crate::LinkRecord { url: "https://x/target-only".into(), ..Default::default() });
    r
}
