pub const MAX_ISSUES: usize = 100_000;
const WORK_BYTES: usize = 64 * 1024 * 1024;

#[derive(Debug, Clone, Copy, Serialize, Deserialize, PartialEq, Eq)]
#[serde(rename_all = "snake_case")]
pub enum Field {
    RequestedUrl,
    FinalUrl,
    Status,
    MediaType,
